using System.Text.Json;
using System.Text.Json.Nodes;
using Cortex.Video.Editing;
namespace Cortex.Video.Composition;
/// <summary>Compiles editorial data into a portable engine-owned executable contract, without rendering.</summary>
public static class HelengineCompositionCompiler {
    public static HelengineCompositionResult Compile(EditScriptDocument script,EditorialDecisionPlanDocument decisions,ResolvedEditPlanDocument resolved,HelengineCapabilities capabilities)=>Compile(script,decisions,resolved,capabilities,decisions.ScriptRef);
    /// <summary>Accepts the current loaded file reference so whitespace/newlines do not confuse byte pins with canonical semantic fingerprints.</summary>
    public static HelengineCompositionResult Compile(EditScriptDocument script,EditorialDecisionPlanDocument decisions,ResolvedEditPlanDocument resolved,HelengineCapabilities capabilities,EditingDocumentReference currentScriptReference) {
        if(resolved.ProjectId!=script.Project.Id || resolved.ScriptRef.Sha256!=currentScriptReference.Sha256 || currentScriptReference.Revision!=script.Revision || resolved.Status!="resolved" || resolved.Timebase!="seconds" || !resolved.Timeline.Select(item=>item.BeatId).SequenceEqual(script.Beats.Select(beat=>beat.Id)))throw new InvalidDataException("Final composition requires a current fully resolved timeline.");if(resolved.ScriptRef.Revision!=script.Revision || !EditingContractValidator.Hash(resolved.EditPlanRef.Sha256) || !EditingContractValidator.Hash(resolved.RecordingTasksRef.Sha256) || resolved.EditPlanRef.ResolutionId!=resolved.ResolutionId || resolved.RecordingTasksRef.ResolutionId!=resolved.ResolutionId)throw new InvalidDataException("Resolved input identities are incomplete or mixed.");var timelineIssues=new List<Cortex.Core.Flows.FlowIssue>();EditingTimelineValidation.Validate(resolved,new(){Script=script},timelineIssues);if(timelineIssues.Count>0)throw new InvalidDataException(string.Join("; ",timelineIssues.Select(issue=>issue.Code+": "+issue.Message)));
        double cursor=0;foreach(var item in resolved.Timeline) {if(Math.Abs(item.Start-cursor)>1e-8 || item.End<=item.Start)throw new InvalidDataException("Resolved timeline contains a gap or invalid interval.");cursor=item.End;var beat=script.Beats.Single(beat=>beat.Id==item.BeatId);if(beat.Audio.Type!=AudioKind.None && (item.Audio.Kind!=BindingKind.Clip || item.Audio.SourceIn is null || item.Audio.SourceOut is null || item.Audio.MediaId is null))throw new InvalidDataException("Resolved speech source and timing are required for final output.");}
        if(!double.IsFinite(cursor) || Math.Abs(cursor-resolved.DurationSec)>1e-8)throw new InvalidDataException("Resolved duration is not exact.");
        var bindings=resolved.Timeline.Select(item=>{var media=resolved.Media.SingleOrDefault(media=>media.Id==item.Video.MediaId);var focus=item.Video.Focus is {SourceRectPixels:not null} f && media!=null?new EditorialFocusResolution(item.BeatId,media.Id,media.Sha256,"resolved",f.SourceRectPixels):null;return new HelengineSceneBinding(item.BeatId,media,item.Start,item.End,item.Audio,focus,item.Video,item.Overlays);}).ToArray();var size=script.Project.Format switch{ProjectFormat.Vertical=>(1080,1920),ProjectFormat.Horizontal=>(1920,1080),_=>(1080,1080)};var result=CompilePlanning(script,decisions,bindings,capabilities,size.Item1,size.Item2,24,resolved.Media);result.RequireExecutable();return result;
    }
    public static HelengineCompositionResult CompilePlanning(EditScriptDocument script,EditorialDecisionPlanDocument decisions,IReadOnlyList<HelengineSceneBinding> bindings,HelengineCapabilities capabilities,int width,int height,int fps=24,IReadOnlyList<MediaSnapshot>? additionalMedia=null) {
        var effective=EditorialDecisionMerge.Effective(decisions);EditorialDecisionValidation.ThrowIfInvalid(effective,script);if(bindings.Count!=script.Beats.Count || !bindings.Select(item=>item.BeatId).SequenceEqual(script.Beats.Select(beat=>beat.Id)) || fps is <1 or >240 || width is <16 or >8192 || height is <16 or >8192 || (long)width*height>33554432)throw new InvalidDataException("Invalid composition bindings or canvas.");var pending=new List<HelengineCompositionPending>();
        if(effective.Scenes.Any(scene=>scene.Conflict))pending.Add(new("decision_conflict","","Resolve human editorial conflicts before rendering."));if(effective.Catalog!=null && effective.Catalog.Fingerprint!=capabilities.Fingerprint)pending.Add(new("catalog_changed","","The pinned effect catalog changed; review and repin without losing human overrides."));
        var snapshots=bindings.Where(binding=>binding.Media!=null).Select(binding=>binding.Media!).Concat(additionalMedia??[]).GroupBy(media=>media.Id).ToDictionary(group=>group.Key,group=>{if(group.Select(media=>JsonSerializer.Serialize(media,EditingJson.Options)).Distinct().Count()!=1)throw new InvalidDataException("Conflicting pinned media identity.");return group.First();});var media=new JsonArray();foreach(var source in snapshots.Values) {if(Path.IsPathRooted(source.Path) || source.Path.Contains(':') || source.Path.Replace('\\','/').Split('/').Contains(".."))throw new InvalidDataException("Only host-resolved relative owned media paths are executable.");media.Add(new JsonObject{["id"]=source.Id,["kind"]=source.Type.ToString().ToLowerInvariant(),["path"]=source.Path,["sha256"]=source.Sha256,["width"]=source.Width,["height"]=source.Height,["duration"]=Time(source.DurationSec??0)});}
        var layers=new JsonArray();var audio=new JsonArray();var audioFades=new List<(string Outgoing,string Incoming,double Seconds)>();var transitions=new JsonArray();double cursor=0;
        for(int index=0;index<bindings.Count;index++) {
            var binding=bindings[index];if(!double.IsFinite(binding.Start+binding.End) || Math.Abs(binding.Start-cursor)>1e-8 || binding.End<=binding.Start)throw new InvalidDataException("Scene timing must be contiguous and finite.");cursor=binding.End;var beat=script.Beats[index];var recipe=effective.Scenes[index].Proposal;var members=new JsonArray();string sceneId="scene-"+beat.Id;string pictureId="picture-"+beat.Id;
            if(binding.Media!=null && binding.Media.Type!=MediaKind.Audio) {var picture=Layer(pictureId,binding.Start,binding.End,0,binding.Media.Id,"media");picture["clip_to_viewport"]=false;picture["fit"]=recipe.Fit;picture["viewport"]=binding.Viewport is{} viewport?JsonSerializer.SerializeToNode(viewport,EditingJson.Options):Viewport(recipe.Presentation,script.Project.Format);if(binding.Media.Type==MediaKind.Video) {if(binding.Video?.SourceIn is not{} sourceIn || binding.Video.SourceOut is not{} sourceOut) {pending.Add(new("video_timing_unresolved",beat.Id,"Video source in/out must be resolved."));}else {picture["source_in"]=Time(sourceIn);picture["source_out"]=Time(sourceOut);}}ApplyMotion(picture,recipe,binding,capabilities,pending,width,height);ApplyEdit(picture,recipe.Editing,binding,snapshots,capabilities,pending);layers.Add(picture);members.Add(pictureId);}
            else if(binding.Video?.Recipe is{} procedural && binding.Video.Kind is BindingKind.Graphic or BindingKind.TitleCard && procedural.TryGetProperty("text",out var text) && text.ValueKind==JsonValueKind.String) {string id="title-"+beat.Id;layers.Add(TextLayer(id,text.GetString()!,binding.Start,binding.End,0,.5));members.Add(id);}
            else {pending.Add(new("visual_unresolved",beat.Id,"Visual source or typed authored title is not resolved."));}
            var overlays=binding.Overlays??(beat.Overlay is null?beat.Overlays??[]:new[]{beat.Overlay}.Concat(beat.Overlays??[]).ToArray());int overlayIndex=0;
            foreach(var overlay in overlays) {double start=binding.Start;if(overlay.Trigger is{} trigger) {if(trigger.Resolved is null || trigger.Resolved.TimingGranularity!=TimingGranularity.Word) {pending.Add(new("overlay_alignment",beat.Id,"Spoken overlay needs actual word timing."));continue;}start+=trigger.Resolved.OffsetSec;}string id="overlay-"+beat.Id+"-"+overlayIndex++;layers.Add(TextLayer(id,overlay.Text,start,binding.End,1,.75));members.Add(id);}
            var group=Layer(sceneId,binding.Start,binding.End,index*10,"","group");group["members"]=members;layers.Add(group);
            if(binding.Audio?.Kind==BindingKind.Clip && binding.Audio.MediaId is{} audioId && binding.Audio.SourceIn is{} audioIn && binding.Audio.SourceOut is{} audioOut && snapshots.TryGetValue(audioId,out var voiceMedia) && voiceMedia.Type is MediaKind.Video or MediaKind.Audio) {audio.Add(Audio("voice-"+beat.Id,audioId,binding.Start,binding.End,audioIn,audioOut,recipe.Editing?.VoiceGain??1,recipe.Editing?.VoiceMuted??false,Envelopes(recipe.Editing?.VoiceEnvelopes??[],binding.End-binding.Start)));}
            else if(beat.Audio.Type!=AudioKind.None) {pending.Add(new("speech_timing_unresolved",beat.Id,"The planning preview has no resolved speech timing."));}
            if(recipe.Editing is{} edit) {int audioIndex=0;foreach(var request in edit.Audio) {if(!snapshots.TryGetValue(request.MediaId,out var sound) || sound.Type is not(MediaKind.Audio or MediaKind.Video) || sound.DurationSec is null || request.SourceInSec+request.DurationSec>sound.DurationSec || request.StartSec+request.DurationSec>binding.End-binding.Start) {pending.Add(new("audio_unresolved",beat.Id,"Audio binding or source handles are missing."));continue;}var envelopes=new JsonArray();foreach(var envelope in request.Envelopes)envelopes.Add(new JsonObject{["type"]=envelope.Type,["start"]=Time(envelope.StartSec),["duration"]=Time(envelope.DurationSec),["from"]=envelope.From,["to"]=envelope.To});audio.Add(Audio("audio-"+beat.Id+"-"+audioIndex++,request.MediaId,binding.Start+request.StartSec,binding.Start+request.StartSec+request.DurationSec,request.SourceInSec,request.SourceInSec+request.DurationSec,request.Gain,request.Muted,envelopes));}
                if(edit.Transition is{} transition) {capabilities.ValidateEffect(transition.EffectId,transition.EffectVersion,transition.Parameters);if(capabilities.Effect(transition.EffectId,transition.EffectVersion).GetProperty("category").GetString()!="transition")throw new InvalidDataException("Effect is not a scene transition.");if(index==0 || transition.DurationSec>binding.End-binding.Start) {pending.Add(new("transition_handles",beat.Id,"Transition requires a previous scene and full overlap."));}else {string previous="scene-"+bindings[index-1].BeatId;ExtendScene(layers,previous,binding.Start+transition.DurationSec,snapshots,pending);transitions.Add(new JsonObject{["id"]="transition-"+beat.Id,["from_layer"]=previous,["to_layer"]=sceneId,["start"]=Time(binding.Start),["duration"]=Time(transition.DurationSec),["effect_id"]=transition.EffectId,["effect_version"]=transition.EffectVersion,["parameters"]=JsonSerializer.SerializeToNode(transition.Parameters)});if(transition.AudioFadeSec>0)audioFades.Add(("voice-"+bindings[index-1].BeatId,"voice-"+beat.Id,transition.AudioFadeSec));}}
            }
        }
        foreach(var fade in audioFades)FadeVoices(audio,fade.Outgoing,fade.Incoming,fade.Seconds);var composition=new JsonObject{["schema"]="helengine.media.composition.v1",["id"]=script.Project.Id,["revision"]=effective.Revision,["width"]=width,["height"]=height,["frame_rate"]=new JsonObject{["numerator"]=fps,["denominator"]=1},["duration"]=Time(cursor),["audio"]=new JsonObject{["enabled"]=audio.Any(clip=>!clip!["muted"]!.GetValue<bool>() && clip["gain"]!.GetValue<double>()>0),["sample_rate"]=48000,["channels"]=2},["media"]=media,["layers"]=layers,["audio_clips"]=audio,["transitions"]=transitions,["background_color"]="#171A21FF"};return new(JsonSerializer.SerializeToElement(composition),pending);
    }
    internal static JsonObject Time(double seconds) {if(!double.IsFinite(seconds))throw new InvalidDataException("Time must be finite.");long numerator=checked((long)Math.Round(seconds*1000000000,MidpointRounding.AwayFromZero));long denominator=1000000000;long a=Math.Abs(numerator),b=denominator;while(b!=0) {(a,b)=(b,a%b);}long divisor=Math.Max(a,1);return new(){["numerator"]=numerator/divisor,["denominator"]=denominator/divisor};}
    private static JsonObject Layer(string id,double start,double end,int order,string mediaId,string kind)=>new(){["id"]=id,["media_id"]=mediaId,["kind"]=kind,["order"]=order,["start"]=Time(start),["end"]=Time(end),["source_in"]=Time(0),["source_out"]=Time(0),["effects"]=new JsonArray(),["animations"]=new JsonArray()};
    private static JsonObject Viewport(string presentation,ProjectFormat format) {if(presentation=="full_frame")return new(){["x"]=0,["y"]=0,["width"]=1,["height"]=1};if(presentation=="side_by_side")return new(){["x"]=.04,["y"]=.18,["width"]=.44,["height"]=.6};return format==ProjectFormat.Vertical?new(){["x"]=.06,["y"]=.18,["width"]=.88,["height"]=.5}:new(){["x"]=.08,["y"]=.08,["width"]=.84,["height"]=.7};}
    private static JsonObject TextLayer(string id,string text,double start,double end,int order,double centerY) {var layer=Layer(id,start,end,order,"","text");layer["text"]=new JsonObject{["cues"]=new JsonArray(new JsonObject{["text"]=text,["start"]=Time(start),["end"]=Time(end),["words"]=new JsonArray()}),["style"]=new JsonObject{["FontFamily"]="Segoe UI",["FontSize"]=48,["Bold"]=true,["Uppercase"]=false,["TextColor"]="#FFFFFF",["Animation"]="None",["CenterY"]=centerY}};return layer;}
    /// <summary>Softens the voice cut of a transition: an equal-power fade-out ending the outgoing voice and a fade-in starting the incoming one, each capped to its clip.</summary>
    public static void FadeVoices(JsonArray audio,string outgoing,string incoming,double seconds) {
        static double Length(JsonObject clip)=>Seconds(clip["end"]!)-Seconds(clip["start"]!);
        if(audio.FirstOrDefault(clip=>clip!["id"]!.GetValue<string>()==outgoing) is JsonObject before) {double fade=Math.Min(seconds,Length(before));if(fade>0)before["envelopes"]!.AsArray().Add(new JsonObject{["type"]="equal_power_out",["start"]=Time(Length(before)-fade),["duration"]=Time(fade),["from"]=1.0,["to"]=0.0});}
        if(audio.FirstOrDefault(clip=>clip!["id"]!.GetValue<string>()==incoming) is JsonObject after) {double fade=Math.Min(seconds,Length(after));if(fade>0)after["envelopes"]!.AsArray().Add(new JsonObject{["type"]="equal_power_in",["start"]=Time(0),["duration"]=Time(fade),["from"]=0.0,["to"]=1.0});}
    }
    private static JsonArray Envelopes(IReadOnlyList<EditorialAudioEnvelope> envelopes,double duration) {var result=new JsonArray();foreach(var envelope in envelopes) {if(envelope.StartSec+envelope.DurationSec>duration)throw new InvalidDataException("Voice envelope exceeds the resolved scene. Review its timing.");result.Add(new JsonObject{["type"]=envelope.Type,["start"]=Time(envelope.StartSec),["duration"]=Time(envelope.DurationSec),["from"]=envelope.From,["to"]=envelope.To});}return result;}
    private static JsonObject Audio(string id,string mediaId,double start,double end,double sourceIn,double sourceOut,double gain,bool muted,JsonArray envelopes)=>new(){["id"]=id,["media_id"]=mediaId,["start"]=Time(start),["end"]=Time(end),["source_in"]=Time(sourceIn),["source_out"]=Time(sourceOut),["gain"]=gain,["muted"]=muted,["envelopes"]=envelopes};
    private static void ApplyMotion(JsonObject layer,EditorialSceneRecipe recipe,HelengineSceneBinding binding,HelengineCapabilities capabilities,List<HelengineCompositionPending> pending,int canvasWidth,int canvasHeight) {
        double duration=binding.End-binding.Start,ratio=duration/recipe.DurationSec;var motion=recipe.Motion;var animations=layer["animations"]!.AsArray();if(recipe.Entry.Type=="fade" && recipe.Entry.DurationSec>0)animations.Add(Track("opacity",[(0,0,"linear.v1"),(Math.Min(recipe.Entry.DurationSec,duration),1,"linear.v1")]));if(motion.Type!="zoom")return;double x=motion.Focus.X,y=motion.Focus.Y;
        if(motion.Focus.Type=="text_region") {var focus=binding.Focus;var image=binding.Media!;if(focus is not{State:"resolved",Region:not null} || focus.MediaId!=image.Id || focus.MediaHash!=image.Sha256) {pending.Add(new("focus_unresolved",binding.BeatId,"Text focus requires a current real source region."));return;}var region=focus.Region;if(!double.IsFinite(region.X+region.Y+region.Width+region.Height) || region.X<0 || region.Y<0 || region.Width<=0 || region.Height<=0 || region.X+region.Width>image.Width || region.Y+region.Height>image.Height)throw new InvalidDataException("Resolved focus is outside the current image.");x=(region.X+region.Width/2)/image.Width;y=(region.Y+region.Height/2)/image.Height;}
        if(binding.Media is{} media && layer["viewport"] is JsonObject viewport) {double w=viewport["width"]!.GetValue<double>()*canvasWidth,h=viewport["height"]!.GetValue<double>()*canvasHeight;double fit=recipe.Fit=="cover"?Math.Max(w/media.Width,h/media.Height):Math.Min(w/media.Width,h/media.Height);x=(x*media.Width*fit+(w-media.Width*fit)/2)/w;y=(y*media.Height*fit+(h-media.Height*fit)/2)/h;}
        string curve=motion.Easing=="ease_in_out"?"smoothstep.v1":"linear.v1";if(!capabilities.Curves.Contains(curve))throw new InvalidDataException("Pinned motion curve is unavailable.");layer["transform"]=new JsonObject{["focus_x"]=Math.Clamp(x,0,1),["focus_y"]=Math.Clamp(y,0,1)};animations.Add(Track("zoom",[(motion.StartSec*ratio,motion.FromScale,curve),((motion.StartSec+motion.DurationSec)*ratio,motion.ToScale,curve)]));
    }
    private static JsonObject Track(string property,IReadOnlyList<(double Time,double Value,string Curve)> frames)=>new(){["property"]=property,["keyframes"]=new JsonArray(frames.Select(frame=>(JsonNode)new JsonObject{["time"]=Time(frame.Time),["value"]=frame.Value,["curve"]=frame.Curve}).ToArray())};
    private static void ApplyEdit(JsonObject layer,EditorialCompositionEdit? edit,HelengineSceneBinding binding,Dictionary<string,MediaSnapshot> media,HelengineCapabilities capabilities,List<HelengineCompositionPending> pending) {
        if(edit is null)return;var transform=layer["transform"] as JsonObject??new JsonObject();if(edit.Transform is{} authored) {var values=new Dictionary<string,double>{{"position_x",authored.PositionX},{"position_y",authored.PositionY},{"scale_x",authored.ScaleX},{"scale_y",authored.ScaleY},{"rotation_deg",authored.RotationDeg},{"opacity",authored.Opacity}};foreach(var value in values) {capabilities.ValidateProperty(value.Key,value.Value);transform[value.Key]=value.Value;}layer["transform"]=transform;}
        foreach(var animation in edit.Animations) {foreach(var frame in animation.Keyframes) {capabilities.ValidateProperty(animation.Property,frame.Value);if(!capabilities.Curves.Contains(frame.Curve))throw new InvalidDataException("Unknown curve version.");if(frame.TimeSec>binding.End-binding.Start)pending.Add(new("animation_timing",binding.BeatId,"Animation exceeds resolved scene timing."));}var tracks=layer["animations"]!.AsArray();foreach(var previous in tracks.Where(track=>track!["property"]!.GetValue<string>()==animation.Property).ToArray())tracks.Remove(previous);tracks.Add(Track(animation.Property,animation.Keyframes.Select(frame=>(frame.TimeSec,frame.Value,frame.Curve)).ToArray()));}
        foreach(var request in edit.Effects) {capabilities.ValidateEffect(request.Id,request.Version,request.Parameters);var descriptor=capabilities.Effect(request.Id,request.Version);if(descriptor.GetProperty("category").GetString()!="layer")throw new InvalidDataException("Effect cannot be used as a layer effect.");string main=descriptor.GetProperty("main_input_role").GetString()!;var roles=descriptor.GetProperty("input_roles").EnumerateArray().Select(role=>role.GetString()!).Where(role=>role!=main).ToHashSet();if(request.Inputs.Keys.Any(role=>!roles.Contains(role)) || roles.Any(role=>!request.Inputs.TryGetValue(role,out var id) || !media.ContainsKey(id)))throw new InvalidDataException("Effect inputs require exact roles and owned media identities.");layer["effects"]!.AsArray().Add(new JsonObject{["id"]=request.Id,["version"]=request.Version,["parameters"]=JsonSerializer.SerializeToNode(request.Parameters),["inputs"]=JsonSerializer.SerializeToNode(request.Inputs)});}
        if(edit.Mask is{} mask) {if(!media.ContainsKey(mask.MediaId) || mask.Channel is not("alpha" or "luma"))throw new InvalidDataException("Mask requires an owned media reference and known channel.");layer["mask"]=JsonSerializer.SerializeToNode(mask,EditingJson.Options);}
    }
    private static void ExtendScene(JsonArray layers,string id,double end,Dictionary<string,MediaSnapshot> media,List<HelengineCompositionPending> pending) {
        var group=layers.Single(layer=>layer!["id"]!.GetValue<string>()==id)!;group["end"]=Time(end);foreach(string childId in group["members"]!.AsArray().Select(member=>member!.GetValue<string>())) {var layer=layers.Single(layer=>layer!["id"]!.GetValue<string>()==childId)!;layer["end"]=Time(end);if(layer["kind"]!.GetValue<string>()=="text") {var cue=layer["text"]!["cues"]!.AsArray().Last();cue!["end"]=Time(end);}else if(media.TryGetValue(layer["media_id"]!.GetValue<string>(),out var source) && source.Type==MediaKind.Video) {double start=Seconds(layer["start"]!),sourceIn=Seconds(layer["source_in"]!),sourceOut=sourceIn+end-start;if(source.DurationSec is null || sourceOut>source.DurationSec)pending.Add(new("transition_handles",id,"Outgoing video lacks source handles for the explicit overlap."));layer["source_out"]=Time(sourceOut);}}
    }
    private static double Seconds(JsonNode time)=>(double)time["numerator"]!.GetValue<long>()/time["denominator"]!.GetValue<long>();
}
